INSERT INTO `kmc_document_segment` VALUES (354, 1001, '泵站运行状态监测指标及关键参数采集知识.docx', 42, '7dfef399-4956-472e-b6ff-9afe235b06da', 1, NULL, '状态监测与数据采集 - 泵站设备故障诊断知识库\n状态监测与数据采集\n泵站设备故障诊断知识库\n分类：知识类/状态监测知识\r\n状态监测与数据采集知识用于指导泵站建立稳定可靠的数据来源，保证故障诊断有据可依。\n一、知识内容\n采集对象\n• 泵组运行数据：流量、压力、扬程、转速、启停状态和运行时长。\n• 机械状态数据：振动速度、振动加速度、轴承温度和噪声。\n• 电气状态数据：三相电流、电压、功率、频率、绝缘和保护动作记录。\n• 工艺环境数据：液位、水质、进出水阀门状态、管网压力和环境温湿度。\n数据质量要求\n• 传感器安装位置应稳定、可维护，避免强电磁干扰和机械冲击。\n• 采集频率应满足诊断需要，振动类数据通常高于普通工艺参数。\n• 异常数据需标注来源，如检修、停机、传感器故障或通信中断。\n二、结构化知识表\n	监测项\n	正常关注点\n	异常判断方向\r\n	压力趋势\n	稳定且随工况变化合理\n	压力突降、波动大、与流量不匹配\r\n	振动趋势\n	长期平稳，无阶跃式升高\n	持续上升、周期性冲击、频谱异常\r\n	温度趋势\n	温升缓慢并保持在允许范围\n	快速升温、局部过热、停机后不下降\r\n	电流趋势\n	三相基本平衡，负载匹配\n	缺相、不平衡、过载、启动电流异常\r\n三、上传与检索建议\n• 建议上传分类：知识类/状态监测知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '状态监测与数据采集 - 泵站设备故障诊断知识库\n状态监测与数据采集\n泵站设备故障诊断知识库\n分类：知识类/状态监测知识\r\n状态监测与数据采集知识用于指导泵站建立稳定可靠的数据来源，保证故障诊断有据可依。\n一、知识内容\n采集对象\n• 泵组运行数据：流量、压力、扬程、转速、启停状态和运行时长。\n• 机械状态数据：振动速度、振动加速度、轴承温度和噪声。\n• 电气状态数据：三相电流、电压、功率、频率、绝缘和保护动作记录。\n• 工艺环境数据：液位、水质、进出水阀门状态、管网压力和环境温湿度。\n数据质量要求\n• 传感器安装位置应稳定、可维护，避免强电磁干扰和机械冲击。\n• 采集频率应满足诊断需要，振动类数据通常高于普通工艺参数。\n• 异常数据需标注来源，如检修、停机、传感器故障或通信中断。\n二、结构化知识表\n	监测项\n	正常关注点\n	异常判断方向\r\n	压力趋势\n	稳定且随工况变化合理\n	压力突降、波动大、与流量不匹配\r\n	振动趋势\n	长期平稳，无阶跃式升高\n	持续上升、周期性冲击、频谱异常\r\n	温度趋势\n	温升缓慢并保持在允许范围\n	快速升温、局部过热、停机后不下降\r\n	电流趋势\n	三相基本平衡，负载匹配\n	缺相、不平衡、过载、启动电流异常\r\n三、上传与检索建议\n• 建议上传分类：知识类/状态监测知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 1, NULL, NULL, '2026-06-01 15:10:01', NULL, NULL, '2026-06-01 15:10:01', NULL);
INSERT INTO `kmc_document_segment` VALUES (355, 1001, '泵站设备常见故障现象识别与异常表现说明.docx', 43, '72d9f007-89a8-4d6a-a3c3-4342bf7f613f', 1, NULL, '常见故障现象识别 - 泵站设备故障诊断知识库\n常见故障现象识别\n泵站设备故障诊断知识库\n分类：知识类/故障现象知识\r\n常见故障现象识别知识用于帮助值班人员快速描述异常，为知识库检索和诊断流程提供入口。\n一、知识内容\n现象描述原则\n• 优先记录“时间、设备、现象、参数、报警、现场环境”。\n• 描述应客观具体，避免只写“设备坏了”“运行异常”等模糊词。\n• 同一故障可同时出现多个现象，应按影响程度排序。\n二、结构化知识表\n	故障现象\n	典型表现\n	优先检查方向\r\n	无法启动\n	启动无反应、启动后立即跳闸\n	电源、控制回路、保护联锁、电机绝缘\r\n	流量不足\n	出水量下降、液位下降慢\n	进水堵塞、阀门开度、叶轮磨损、管路漏气\r\n	压力异常\n	出水压力低或波动明显\n	汽蚀、管道阻塞、压力表故障、阀门异常\r\n	振动过大\n	机座抖动、轴承冲击声、联轴器摆动\n	轴承、联轴器、转子不平衡、基础松动\r\n	温度过高\n	电机或轴承温升明显\n	润滑、散热、过载、轴承损伤\r\n	泄漏\n	机械密封、法兰、阀门处渗漏\n	密封磨损、紧固不足、垫片损坏、压力过高\r\n三、上传与检索建议\n• 建议上传分类：知识类/故障现象知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '常见故障现象识别 - 泵站设备故障诊断知识库\n常见故障现象识别\n泵站设备故障诊断知识库\n分类：知识类/故障现象知识\r\n常见故障现象识别知识用于帮助值班人员快速描述异常，为知识库检索和诊断流程提供入口。\n一、知识内容\n现象描述原则\n• 优先记录“时间、设备、现象、参数、报警、现场环境”。\n• 描述应客观具体，避免只写“设备坏了”“运行异常”等模糊词。\n• 同一故障可同时出现多个现象，应按影响程度排序。\n二、结构化知识表\n	故障现象\n	典型表现\n	优先检查方向\r\n	无法启动\n	启动无反应、启动后立即跳闸\n	电源、控制回路、保护联锁、电机绝缘\r\n	流量不足\n	出水量下降、液位下降慢\n	进水堵塞、阀门开度、叶轮磨损、管路漏气\r\n	压力异常\n	出水压力低或波动明显\n	汽蚀、管道阻塞、压力表故障、阀门异常\r\n	振动过大\n	机座抖动、轴承冲击声、联轴器摆动\n	轴承、联轴器、转子不平衡、基础松动\r\n	温度过高\n	电机或轴承温升明显\n	润滑、散热、过载、轴承损伤\r\n	泄漏\n	机械密封、法兰、阀门处渗漏\n	密封磨损、紧固不足、垫片损坏、压力过高\r\n三、上传与检索建议\n• 建议上传分类：知识类/故障现象知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:10:02', NULL, NULL, '2026-06-01 15:10:02', NULL);
INSERT INTO `kmc_document_segment` VALUES (356, 1001, '泵站主要设备组成结构及工作原理基础知识.docx', 41, 'b433ae70-e648-417e-9dd2-0e275bb4c8ef', 1, NULL, '设备基础知识 - 泵站设备故障诊断知识库\n设备基础知识\n泵站设备故障诊断知识库\n分类：知识类/设备基础知识\r\n泵站设备基础知识用于统一运维人员对主要设备、关键部件和运行参数的理解，是后续故障诊断、案例沉淀和维修决策的基础。\n一、知识内容\n主要设备组成\n• 水泵：负责将水体加压输送，是泵站的核心动力设备。\n• 电机：为水泵提供旋转动力，需关注电流、温升、绝缘和振动。\n• 管道与阀门：承担输水、截断、调节和防倒流功能。\n• 传感器与仪表：采集压力、流量、液位、温度、振动、电流等状态数据。\n• 控制柜与变频器：完成启停控制、联锁保护、调速和报警。\n关键运行参数\n二、结构化知识表\n	参数\n	含义\n	异常提示\r\n	流量\n	单位时间内输送水量\n	流量下降可能与堵塞、阀门未开足、叶轮磨损有关\r\n	扬程/压力\n	泵提升水体的能力\n	压力不足可能与汽蚀、漏气、管路阻力异常有关\r\n	振动\n	反映设备机械状态\n	振动增大可能提示轴承、联轴器、地脚或不平衡问题\r\n	温度\n	电机、轴承、密封等部位热状态\n	温升过快可能与润滑不良、负载过大、散热差有关\r\n	电流\n	电机运行负荷指标\n	电流异常可能与过载、缺相、堵转或电气故障有关\r\n三、上传与检索建议\n• 建议上传分类：知识类/设备基础知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '设备基础知识 - 泵站设备故障诊断知识库\n设备基础知识\n泵站设备故障诊断知识库\n分类：知识类/设备基础知识\r\n泵站设备基础知识用于统一运维人员对主要设备、关键部件和运行参数的理解，是后续故障诊断、案例沉淀和维修决策的基础。\n一、知识内容\n主要设备组成\n• 水泵：负责将水体加压输送，是泵站的核心动力设备。\n• 电机：为水泵提供旋转动力，需关注电流、温升、绝缘和振动。\n• 管道与阀门：承担输水、截断、调节和防倒流功能。\n• 传感器与仪表：采集压力、流量、液位、温度、振动、电流等状态数据。\n• 控制柜与变频器：完成启停控制、联锁保护、调速和报警。\n关键运行参数\n二、结构化知识表\n	参数\n	含义\n	异常提示\r\n	流量\n	单位时间内输送水量\n	流量下降可能与堵塞、阀门未开足、叶轮磨损有关\r\n	扬程/压力\n	泵提升水体的能力\n	压力不足可能与汽蚀、漏气、管路阻力异常有关\r\n	振动\n	反映设备机械状态\n	振动增大可能提示轴承、联轴器、地脚或不平衡问题\r\n	温度\n	电机、轴承、密封等部位热状态\n	温升过快可能与润滑不良、负载过大、散热差有关\r\n	电流\n	电机运行负荷指标\n	电流异常可能与过载、缺相、堵转或电气故障有关\r\n三、上传与检索建议\n• 建议上传分类：知识类/设备基础知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:15:00', NULL, NULL, '2026-06-01 15:15:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (357, 1001, '泵站运行状态监测指标及关键参数采集知识.docx', 42, '43e742e8-aac6-4dc0-a085-5a278935cf64', 1, NULL, '状态监测与数据采集 - 泵站设备故障诊断知识库\n状态监测与数据采集\n泵站设备故障诊断知识库\n分类：知识类/状态监测知识\r\n状态监测与数据采集知识用于指导泵站建立稳定可靠的数据来源，保证故障诊断有据可依。\n一、知识内容\n采集对象\n• 泵组运行数据：流量、压力、扬程、转速、启停状态和运行时长。\n• 机械状态数据：振动速度、振动加速度、轴承温度和噪声。\n• 电气状态数据：三相电流、电压、功率、频率、绝缘和保护动作记录。\n• 工艺环境数据：液位、水质、进出水阀门状态、管网压力和环境温湿度。\n数据质量要求\n• 传感器安装位置应稳定、可维护，避免强电磁干扰和机械冲击。\n• 采集频率应满足诊断需要，振动类数据通常高于普通工艺参数。\n• 异常数据需标注来源，如检修、停机、传感器故障或通信中断。\n二、结构化知识表\n	监测项\n	正常关注点\n	异常判断方向\r\n	压力趋势\n	稳定且随工况变化合理\n	压力突降、波动大、与流量不匹配\r\n	振动趋势\n	长期平稳，无阶跃式升高\n	持续上升、周期性冲击、频谱异常\r\n	温度趋势\n	温升缓慢并保持在允许范围\n	快速升温、局部过热、停机后不下降\r\n	电流趋势\n	三相基本平衡，负载匹配\n	缺相、不平衡、过载、启动电流异常\r\n三、上传与检索建议\n• 建议上传分类：知识类/状态监测知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '状态监测与数据采集 - 泵站设备故障诊断知识库\n状态监测与数据采集\n泵站设备故障诊断知识库\n分类：知识类/状态监测知识\r\n状态监测与数据采集知识用于指导泵站建立稳定可靠的数据来源，保证故障诊断有据可依。\n一、知识内容\n采集对象\n• 泵组运行数据：流量、压力、扬程、转速、启停状态和运行时长。\n• 机械状态数据：振动速度、振动加速度、轴承温度和噪声。\n• 电气状态数据：三相电流、电压、功率、频率、绝缘和保护动作记录。\n• 工艺环境数据：液位、水质、进出水阀门状态、管网压力和环境温湿度。\n数据质量要求\n• 传感器安装位置应稳定、可维护，避免强电磁干扰和机械冲击。\n• 采集频率应满足诊断需要，振动类数据通常高于普通工艺参数。\n• 异常数据需标注来源，如检修、停机、传感器故障或通信中断。\n二、结构化知识表\n	监测项\n	正常关注点\n	异常判断方向\r\n	压力趋势\n	稳定且随工况变化合理\n	压力突降、波动大、与流量不匹配\r\n	振动趋势\n	长期平稳，无阶跃式升高\n	持续上升、周期性冲击、频谱异常\r\n	温度趋势\n	温升缓慢并保持在允许范围\n	快速升温、局部过热、停机后不下降\r\n	电流趋势\n	三相基本平衡，负载匹配\n	缺相、不平衡、过载、启动电流异常\r\n三、上传与检索建议\n• 建议上传分类：知识类/状态监测知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:15:01', NULL, NULL, '2026-06-01 15:15:01', NULL);
INSERT INTO `kmc_document_segment` VALUES (358, 1001, '泵站设备故障原因分类分析与影响因素说明.docx', 44, '73d8875f-78f4-45b7-afd3-7a2a44f2c647', 1, NULL, '故障原因分析 - 泵站设备故障诊断知识库\n故障原因分析\n泵站设备故障诊断知识库\n分类：知识类/故障原因知识\r\n故障原因分析知识从系统角度梳理故障根源，避免只处理表面现象而忽略深层原因。\n一、知识内容\n原因分析思路\n• 先确认故障是否真实存在，排除仪表误报、通信异常和人为操作影响。\n• 再从机械、电气、水力、控制、环境和维护六类原因逐步排查。\n• 对于重复故障，应追溯设计选型、安装质量、运行工况和维护制度。\n二、结构化知识表\n	原因类别\n	典型原因\n	关联现象\r\n	机械类\n	轴承磨损、联轴器不对中、转子不平衡、地脚松动\n	振动大、噪声大、温度高\r\n	电气类\n	缺相、接触器故障、绝缘下降、过载保护动作\n	无法启动、跳闸、电流异常\r\n	水力类\n	汽蚀、进水不足、叶轮堵塞、管路阻力增加\n	流量不足、压力波动、噪声异常\r\n	控制类\n	PLC逻辑错误、传感器失准、变频器参数不当\n	误报警、启停异常、频率波动\r\n	维护类\n	润滑不足、备件质量差、检修装配不当\n	故障反复、寿命缩短、效率下降\r\n三、上传与检索建议\n• 建议上传分类：知识类/故障原因知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '故障原因分析 - 泵站设备故障诊断知识库\n故障原因分析\n泵站设备故障诊断知识库\n分类：知识类/故障原因知识\r\n故障原因分析知识从系统角度梳理故障根源，避免只处理表面现象而忽略深层原因。\n一、知识内容\n原因分析思路\n• 先确认故障是否真实存在，排除仪表误报、通信异常和人为操作影响。\n• 再从机械、电气、水力、控制、环境和维护六类原因逐步排查。\n• 对于重复故障，应追溯设计选型、安装质量、运行工况和维护制度。\n二、结构化知识表\n	原因类别\n	典型原因\n	关联现象\r\n	机械类\n	轴承磨损、联轴器不对中、转子不平衡、地脚松动\n	振动大、噪声大、温度高\r\n	电气类\n	缺相、接触器故障、绝缘下降、过载保护动作\n	无法启动、跳闸、电流异常\r\n	水力类\n	汽蚀、进水不足、叶轮堵塞、管路阻力增加\n	流量不足、压力波动、噪声异常\r\n	控制类\n	PLC逻辑错误、传感器失准、变频器参数不当\n	误报警、启停异常、频率波动\r\n	维护类\n	润滑不足、备件质量差、检修装配不当\n	故障反复、寿命缩短、效率下降\r\n三、上传与检索建议\n• 建议上传分类：知识类/故障原因知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:15:02', NULL, NULL, '2026-06-01 15:15:02', NULL);
INSERT INTO `kmc_document_segment` VALUES (359, 1001, '泵站设备故障诊断方法与现场排查流程知识.docx', 45, '792cc176-c5fa-40ea-b4cd-fa9b44c89ecb', 1, NULL, '故障诊断方法与判据 - 泵站设备故障诊断知识库\n故障诊断方法与判据\n泵站设备故障诊断知识库\n分类：知识类/诊断方法知识\r\n故障诊断方法与判据用于指导现场人员将现象、数据和经验结合起来，形成可复用的诊断流程。\n一、知识内容\n通用诊断流程\n• 确认报警和运行状态，记录故障发生时间与工况。\n• 查看趋势数据，判断异常是突发、渐变还是周期性。\n• 进行现场检查，包括声音、振动、温度、泄漏和异味。\n• 结合电气、机械、水力数据交叉验证，形成初步判断。\n• 实施处理措施后试运行，确认参数恢复并记录结果。\n二、结构化知识表\n	诊断方法\n	适用场景\n	判断要点\r\n	趋势分析\n	流量、压力、温度、电流缓慢变化\n	关注持续上升/下降、阶跃变化和周期波动\r\n	振动分析\n	轴承、联轴器、转子类故障\n	关注冲击成分、倍频、边频和振动方向\r\n	红外测温\n	电机、轴承、接线端子过热\n	关注局部热点和同类设备温差\r\n	电流分析\n	过载、缺相、堵转、变频异常\n	关注三相平衡、启动电流和负载匹配\r\n	现场听诊\n	轴承、汽蚀、摩擦碰擦\n	关注尖锐冲击声、砂石声、周期摩擦声\r\n三、上传与检索建议\n• 建议上传分类：知识类/诊断方法知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '故障诊断方法与判据 - 泵站设备故障诊断知识库\n故障诊断方法与判据\n泵站设备故障诊断知识库\n分类：知识类/诊断方法知识\r\n故障诊断方法与判据用于指导现场人员将现象、数据和经验结合起来，形成可复用的诊断流程。\n一、知识内容\n通用诊断流程\n• 确认报警和运行状态，记录故障发生时间与工况。\n• 查看趋势数据，判断异常是突发、渐变还是周期性。\n• 进行现场检查，包括声音、振动、温度、泄漏和异味。\n• 结合电气、机械、水力数据交叉验证，形成初步判断。\n• 实施处理措施后试运行，确认参数恢复并记录结果。\n二、结构化知识表\n	诊断方法\n	适用场景\n	判断要点\r\n	趋势分析\n	流量、压力、温度、电流缓慢变化\n	关注持续上升/下降、阶跃变化和周期波动\r\n	振动分析\n	轴承、联轴器、转子类故障\n	关注冲击成分、倍频、边频和振动方向\r\n	红外测温\n	电机、轴承、接线端子过热\n	关注局部热点和同类设备温差\r\n	电流分析\n	过载、缺相、堵转、变频异常\n	关注三相平衡、启动电流和负载匹配\r\n	现场听诊\n	轴承、汽蚀、摩擦碰擦\n	关注尖锐冲击声、砂石声、周期摩擦声\r\n三、上传与检索建议\n• 建议上传分类：知识类/诊断方法知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:15:02', NULL, NULL, '2026-06-01 15:15:02', NULL);
INSERT INTO `kmc_document_segment` VALUES (360, 1001, '泵站常见故障排查步骤与解决方案知识.docx', 46, 'be9a678a-a169-46f6-85b3-783e1188081a', 1, NULL, '典型故障案例库 - 泵站设备故障诊断知识库\n典型故障案例库\n泵站设备故障诊断知识库\n分类：知识类/典型案例知识\r\n典型故障案例库用于沉淀运维经验，建议每个案例统一采用“现象-原因-诊断-处理-效果-经验”结构。\n一、知识内容\n案例记录模板\n• 故障现象：描述报警、参数变化和现场表现。\n• 原因分析：说明直接原因和深层原因。\n• 诊断过程：列出检查步骤、检测数据和判断依据。\n• 处理措施：记录维修动作、更换部件和复位验证。\n• 经验总结：给出预防措施和后续关注点。\n二、结构化知识表\n	案例\n	故障现象\n	原因判断\n	处理措施\r\n	轴承内圈早期故障\n	振动趋势升高，频谱出现冲击成分\n	轴承疲劳点蚀或润滑不足\n	停机检查轴承，补充/更换润滑脂，必要时更换轴承\r\n	水泵汽蚀\n	泵体噪声似砂石声，压力波动\n	进水不足或吸程过高\n	检查进水液位、清理滤网、调整阀门开度\r\n	机械密封泄漏\n	泵端连续滴漏或喷漏\n	密封面磨损、弹簧失效或安装偏差\n	更换机械密封，检查轴套磨损和端面清洁度\r\n	叶轮堵塞\n	流量下降，电流变化异常\n	杂物进入叶轮或进水口堵塞\n	停机排空后清理叶轮和格栅，复测流量\r\n	电机过热\n	外壳温度升高并伴随过载报警\n	负载过大、散热差或缺相\n	检查风扇、三相电流、接线和负载情况\r\n三、上传与检索建议\n• 建议上传分类：知识类/典型案例知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '典型故障案例库 - 泵站设备故障诊断知识库\n典型故障案例库\n泵站设备故障诊断知识库\n分类：知识类/典型案例知识\r\n典型故障案例库用于沉淀运维经验，建议每个案例统一采用“现象-原因-诊断-处理-效果-经验”结构。\n一、知识内容\n案例记录模板\n• 故障现象：描述报警、参数变化和现场表现。\n• 原因分析：说明直接原因和深层原因。\n• 诊断过程：列出检查步骤、检测数据和判断依据。\n• 处理措施：记录维修动作、更换部件和复位验证。\n• 经验总结：给出预防措施和后续关注点。\n二、结构化知识表\n	案例\n	故障现象\n	原因判断\n	处理措施\r\n	轴承内圈早期故障\n	振动趋势升高，频谱出现冲击成分\n	轴承疲劳点蚀或润滑不足\n	停机检查轴承，补充/更换润滑脂，必要时更换轴承\r\n	水泵汽蚀\n	泵体噪声似砂石声，压力波动\n	进水不足或吸程过高\n	检查进水液位、清理滤网、调整阀门开度\r\n	机械密封泄漏\n	泵端连续滴漏或喷漏\n	密封面磨损、弹簧失效或安装偏差\n	更换机械密封，检查轴套磨损和端面清洁度\r\n	叶轮堵塞\n	流量下降，电流变化异常\n	杂物进入叶轮或进水口堵塞\n	停机排空后清理叶轮和格栅，复测流量\r\n	电机过热\n	外壳温度升高并伴随过载报警\n	负载过大、散热差或缺相\n	检查风扇、三相电流、接线和负载情况\r\n三、上传与检索建议\n• 建议上传分类：知识类/典型案例知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:20:00', NULL, NULL, '2026-06-01 15:20:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (361, 1001, '泵站设备维修处理措施与部件检修更换知识.docx', 47, 'e297cf71-b9e6-4841-94fd-2a6cc50149a3', 1, NULL, '维修处理措施 - 泵站设备故障诊断知识库\n维修处理措施\n泵站设备故障诊断知识库\n分类：知识类/维修处理知识\r\n维修处理措施用于将诊断结果转化为可执行的处置步骤，确保维修过程安全、规范、可追溯。\n一、知识内容\n维修基本原则\n• 先安全隔离，后拆检处理；先确认风险，后执行作业。\n• 先处理影响安全和连续供水的故障，再处理一般性缺陷。\n• 维修后必须进行试运行、参数复核和记录归档。\n常用处理动作\n• 紧固地脚螺栓、联轴器防护罩、法兰连接和接线端子。\n• 清理进水口、过滤网、叶轮和管路杂物。\n• 更换轴承、机械密封、密封垫、压力表和传感器。\n• 校正联轴器同轴度，检查基础沉降和管道应力。\n二、结构化知识表\n	故障类型\n	处理措施\n	验证方式\r\n	振动过大\n	检查轴承、联轴器、基础和转子平衡\n	复测振动值，确认无异常噪声\r\n	流量不足\n	清理堵塞，调整阀门，检查叶轮和管路\n	复测流量、压力和液位变化\r\n	温度过高\n	检查润滑、散热、负载和电气接线\n	观察温升趋势是否恢复稳定\r\n	频繁跳闸\n	检查保护设定、绝缘、电流和控制回路\n	空载/带载试运行，确认保护不误动\r\n三、上传与检索建议\n• 建议上传分类：知识类/维修处理知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '维修处理措施 - 泵站设备故障诊断知识库\n维修处理措施\n泵站设备故障诊断知识库\n分类：知识类/维修处理知识\r\n维修处理措施用于将诊断结果转化为可执行的处置步骤，确保维修过程安全、规范、可追溯。\n一、知识内容\n维修基本原则\n• 先安全隔离，后拆检处理；先确认风险，后执行作业。\n• 先处理影响安全和连续供水的故障，再处理一般性缺陷。\n• 维修后必须进行试运行、参数复核和记录归档。\n常用处理动作\n• 紧固地脚螺栓、联轴器防护罩、法兰连接和接线端子。\n• 清理进水口、过滤网、叶轮和管路杂物。\n• 更换轴承、机械密封、密封垫、压力表和传感器。\n• 校正联轴器同轴度，检查基础沉降和管道应力。\n二、结构化知识表\n	故障类型\n	处理措施\n	验证方式\r\n	振动过大\n	检查轴承、联轴器、基础和转子平衡\n	复测振动值，确认无异常噪声\r\n	流量不足\n	清理堵塞，调整阀门，检查叶轮和管路\n	复测流量、压力和液位变化\r\n	温度过高\n	检查润滑、散热、负载和电气接线\n	观察温升趋势是否恢复稳定\r\n	频繁跳闸\n	检查保护设定、绝缘、电流和控制回路\n	空载/带载试运行，确认保护不误动\r\n三、上传与检索建议\n• 建议上传分类：知识类/维修处理知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:20:01', NULL, NULL, '2026-06-01 15:20:01', NULL);
INSERT INTO `kmc_document_segment` VALUES (362, 1001, '泵站典型故障案例分析及处理经验总结.docx', 48, '0ccf5a34-c85f-46e7-b268-f2d026c67783', 1, NULL, '预防维护与点检 - 泵站设备故障诊断知识库\n预防维护与点检\n泵站设备故障诊断知识库\n分类：知识类/预防维护知识\r\n预防维护与点检知识用于把故障处理前移，通过周期性检查和维护降低突发故障概率。\n一、知识内容\n点检要求\n• 点检记录应包含设备编号、时间、人员、参数、异常描述和处理结果。\n• 关键设备建议建立趋势台账，长期跟踪振动、温度、电流和泄漏情况。\n• 对重复异常应形成专项整改，不应只做临时恢复。\n二、结构化知识表\n	周期\n	点检内容\n	重点记录\r\n	每日\n	巡查声音、振动、温度、压力、流量和泄漏\n	异常声响、温升、滴漏、报警信息\r\n	每周\n	检查阀门开度、传感器状态、控制柜指示和备用泵\n	备用泵试转、仪表偏差、通信状态\r\n	每月\n	检查润滑、联轴器、地脚螺栓、电机风道和接线端子\n	润滑状态、紧固情况、端子温度\r\n	每季度\n	进行振动检测、绝缘测试和保护联锁试验\n	趋势报告、绝缘电阻、联锁动作结果\r\n	每年\n	开展泵组综合检修和效率评估\n	维修清单、备件更换、性能对比\r\n三、上传与检索建议\n• 建议上传分类：知识类/预防维护知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '预防维护与点检 - 泵站设备故障诊断知识库\n预防维护与点检\n泵站设备故障诊断知识库\n分类：知识类/预防维护知识\r\n预防维护与点检知识用于把故障处理前移，通过周期性检查和维护降低突发故障概率。\n一、知识内容\n点检要求\n• 点检记录应包含设备编号、时间、人员、参数、异常描述和处理结果。\n• 关键设备建议建立趋势台账，长期跟踪振动、温度、电流和泄漏情况。\n• 对重复异常应形成专项整改，不应只做临时恢复。\n二、结构化知识表\n	周期\n	点检内容\n	重点记录\r\n	每日\n	巡查声音、振动、温度、压力、流量和泄漏\n	异常声响、温升、滴漏、报警信息\r\n	每周\n	检查阀门开度、传感器状态、控制柜指示和备用泵\n	备用泵试转、仪表偏差、通信状态\r\n	每月\n	检查润滑、联轴器、地脚螺栓、电机风道和接线端子\n	润滑状态、紧固情况、端子温度\r\n	每季度\n	进行振动检测、绝缘测试和保护联锁试验\n	趋势报告、绝缘电阻、联锁动作结果\r\n	每年\n	开展泵组综合检修和效率评估\n	维修清单、备件更换、性能对比\r\n三、上传与检索建议\n• 建议上传分类：知识类/预防维护知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:20:02', NULL, NULL, '2026-06-01 15:20:02', NULL);
INSERT INTO `kmc_document_segment` VALUES (363, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, 'e09dba6d-a1b8-4d59-8f3c-fe03bdc425b3', 1, NULL, '泵站常见故障排查及解决方案库 · 预防维护知识\n泵站常见故障排查及解决方案库\r\n09\n泵站设备日常巡检保养与预防性维护知识\nDaily Inspection, Maintenance and Preventive Maintenance Knowledge for Pump Station Equipment\r\n	文件定位\n所属分类：05_案例与预防维护\n文件用途：规范泵站设备日常巡检、维护保养和预防性维护管理\n适用对象：泵站运行人员、检修人员、设备管理人员、知识库维护人员\n关键词：巡检、保养、润滑、点检、预防维护、隐患排查、设备状态\r\n版本：V1.0 类型：知识库数据文件 格式：DOCX\r\n文件说明\n本文档用于整理泵站设备日常巡检、保养维护和预防性维护相关知识，重点覆盖巡检项目、检查方法、维护周期、保养措施、隐患预防、记录模板和现场注意事项。文档内容可作为泵站常见故障排查及解决方案库中“预防维护知识”数据文件使用。\n	文件名称\n	09_泵站设备日常巡检保养与预防性维护知识.docx\r\n	所属知识库\n	泵站常见故障排查及解决方案库\r\n	所属分类\n	05_案例与预防维护\r\n	数据编号\n	09\r\n	文件描述\n	整理泵站设备日常巡检、保养维护、预防性维护和隐患排查知识，帮助运维人员提前发现设备异常，降低故障发生概率。\r\n	文件备注\n	用于支撑泵站设备预防维护、巡检管理和故障预警工作，可结合现场制度、设备说明书和运行记录进行补充完善。\r\n目录\n1. 适用范围与维护目标\n2. 日常巡检基本要求\n3. 泵站设备巡检项目清单\n4. 设备保养维护知识\n5. 预防性维护策略\n6. 常见隐患与预防措施\n7. 巡检与维护记录模板\n8. 安全注意事项\n9. 知识库使用建议\r\n1. 适用范围与维护目标\n本文件适用于各类泵站设备的日常运行维护，包括水泵、电机、阀门、管道、控制柜、传感器、仪表、液位设施、排水设施和辅助设备等。维护工作应坚持“日常巡检为基础、状态监测为支撑、预防维护为重点、故障处理为补充”的原则。\n	维护目标\n• 及时发现设备异常，防止小隐患发展为大故障。\n• 保持水泵、电机、阀门、管道和控制系统处于可靠运行状态。\n• 延长设备使用寿命，降低突发停机和维修成本。\n• 形成可追溯的巡检、保养、维修和隐患整改记录。\r\n2. 日常巡检基本要求\n日常巡检应按照固定路线、固定项目、固定标准、固定记录的方式开展。巡检人员应重点观察设备声音、振动、温度、压力、流量、电流、电压、液位、泄漏、异味和控制状态等信息。对异常情况应及时记录、上报、', '泵站常见故障排查及解决方案库 · 预防维护知识\n泵站常见故障排查及解决方案库\r\n09\n泵站设备日常巡检保养与预防性维护知识\nDaily Inspection, Maintenance and Preventive Maintenance Knowledge for Pump Station Equipment\r\n	文件定位\n所属分类：05_案例与预防维护\n文件用途：规范泵站设备日常巡检、维护保养和预防性维护管理\n适用对象：泵站运行人员、检修人员、设备管理人员、知识库维护人员\n关键词：巡检、保养、润滑、点检、预防维护、隐患排查、设备状态\r\n版本：V1.0 类型：知识库数据文件 格式：DOCX\r\n文件说明\n本文档用于整理泵站设备日常巡检、保养维护和预防性维护相关知识，重点覆盖巡检项目、检查方法、维护周期、保养措施、隐患预防、记录模板和现场注意事项。文档内容可作为泵站常见故障排查及解决方案库中“预防维护知识”数据文件使用。\n	文件名称\n	09_泵站设备日常巡检保养与预防性维护知识.docx\r\n	所属知识库\n	泵站常见故障排查及解决方案库\r\n	所属分类\n	05_案例与预防维护\r\n	数据编号\n	09\r\n	文件描述\n	整理泵站设备日常巡检、保养维护、预防性维护和隐患排查知识，帮助运维人员提前发现设备异常，降低故障发生概率。\r\n	文件备注\n	用于支撑泵站设备预防维护、巡检管理和故障预警工作，可结合现场制度、设备说明书和运行记录进行补充完善。\r\n目录\n1. 适用范围与维护目标\n2. 日常巡检基本要求\n3. 泵站设备巡检项目清单\n4. 设备保养维护知识\n5. 预防性维护策略\n6. 常见隐患与预防措施\n7. 巡检与维护记录模板\n8. 安全注意事项\n9. 知识库使用建议\r\n1. 适用范围与维护目标\n本文件适用于各类泵站设备的日常运行维护，包括水泵、电机、阀门、管道、控制柜、传感器、仪表、液位设施、排水设施和辅助设备等。维护工作应坚持“日常巡检为基础、状态监测为支撑、预防维护为重点、故障处理为补充”的原则。\n	维护目标\n• 及时发现设备异常，防止小隐患发展为大故障。\n• 保持水泵、电机、阀门、管道和控制系统处于可靠运行状态。\n• 延长设备使用寿命，降低突发停机和维修成本。\n• 形成可追溯的巡检、保养、维修和隐患整改记录。\r\n2. 日常巡检基本要求\n日常巡检应按照固定路线、固定项目、固定标准、固定记录的方式开展。巡检人员应重点观察设备声音、振动、温度、压力、流量、电流、电压、液位、泄漏、异味和控制状态等信息。对异常情况应及时记录、上报、', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (364, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, 'ab697407-71fa-45ec-979b-bd16321c292b', 2, NULL, '基本要求\n日常巡检应按照固定路线、固定项目、固定标准、固定记录的方式开展。巡检人员应重点观察设备声音、振动、温度、压力、流量、电流、电压、液位、泄漏、异味和控制状态等信息。对异常情况应及时记录、上报、复查，并根据严重程度采取处置措施。\n	要求类别\n	具体要求\n	执行要点\r\n	巡检频次\n	运行期间按班次或规定周期巡检，重点设备适当增加巡检次数。\n	高温、强降雨、满负荷运行、设备刚检修后应加强巡查。\r\n	巡检路线\n	按照泵房入口、控制柜、水泵机组、管路阀门、仪表传感器、排水设施的顺序进行。\n	避免漏检，必要时在现场张贴巡检路线图。\r\n	巡检方法\n	采用看、听、摸、闻、测、查相结合的方法。\n	不得用手直接接触高温、带电、旋转部位。\r\n	异常处理\n	发现异常后先确认现象，再判断风险等级并报告处理。\n	严禁在原因不明时盲目强行运行设备。\r\n	记录要求\n	巡检情况、异常现象、处理意见和复查结果应及时记录。\n	记录要真实、完整、可追溯。\r\n3. 泵站设备巡检项目清单\n3.1 水泵机组巡检项目\n	巡检对象\n	检查内容\n	正常状态参考\n	异常提示\r\n	水泵本体\n	检查泵体外观、连接螺栓、基础固定、运行声音。\n	泵体无明显裂纹，螺栓无松动，运行声音均匀。\n	异常噪声、泵体晃动、螺栓松动可能提示机械故障。\r\n	轴承部位\n	检查轴承温度、润滑状态、振动情况。\n	温升平稳，润滑良好，振动无明显增大。\n	过热、异响、振动变大可能提示轴承磨损或润滑不足。\r\n	机械密封\n	检查密封处是否渗漏、滴漏或喷漏。\n	密封处无明显泄漏或仅有轻微允许渗漏。\n	泄漏增大可能提示密封磨损、安装偏差或压力异常。\r\n	进出水管路\n	检查管道连接、法兰、支架和水流状态。\n	管道无变形，法兰无渗漏，支架稳固。\n	管道振动、漏水、压力波动可能提示堵塞或水锤风险。\r\n	运行参数\n	核对流量、压力、电流、转速等参数。\n	参数处于正常运行范围内，变化趋势平稳。\n	流量不足、压力异常、电流升高需进一步排查。\r\n3.2 电机与电气系统巡检项目\n	巡检对象\n	检查内容\n	正常状态参考\n	异常提示\r\n	电机外壳\n	检查温度、噪声、振动、外观和接地情况。\n	外壳温度正常，接地可靠，运行平稳。\n	温度过高、异味、异常振动可能提示过载或绝缘问题。\r\n	电流电压\n	查看三相电流、电压是否平衡。\n	三相参数基本平衡，无明显波动。\n	电流偏高、电压不平衡可能导致电机发热或跳闸。\r\n	控制柜\n	检查指示灯、按钮、开关、接触器、继电器和显示屏。\n	指示正常，操作灵敏，柜内无异味和异响。\n	焦味、打火声、接线发热应立即停机检查。\r\n	电缆接线\n	检查线缆外皮、端子紧固和穿管保护。\n	线缆无破损，端', '基本要求\n日常巡检应按照固定路线、固定项目、固定标准、固定记录的方式开展。巡检人员应重点观察设备声音、振动、温度、压力、流量、电流、电压、液位、泄漏、异味和控制状态等信息。对异常情况应及时记录、上报、复查，并根据严重程度采取处置措施。\n	要求类别\n	具体要求\n	执行要点\r\n	巡检频次\n	运行期间按班次或规定周期巡检，重点设备适当增加巡检次数。\n	高温、强降雨、满负荷运行、设备刚检修后应加强巡查。\r\n	巡检路线\n	按照泵房入口、控制柜、水泵机组、管路阀门、仪表传感器、排水设施的顺序进行。\n	避免漏检，必要时在现场张贴巡检路线图。\r\n	巡检方法\n	采用看、听、摸、闻、测、查相结合的方法。\n	不得用手直接接触高温、带电、旋转部位。\r\n	异常处理\n	发现异常后先确认现象，再判断风险等级并报告处理。\n	严禁在原因不明时盲目强行运行设备。\r\n	记录要求\n	巡检情况、异常现象、处理意见和复查结果应及时记录。\n	记录要真实、完整、可追溯。\r\n3. 泵站设备巡检项目清单\n3.1 水泵机组巡检项目\n	巡检对象\n	检查内容\n	正常状态参考\n	异常提示\r\n	水泵本体\n	检查泵体外观、连接螺栓、基础固定、运行声音。\n	泵体无明显裂纹，螺栓无松动，运行声音均匀。\n	异常噪声、泵体晃动、螺栓松动可能提示机械故障。\r\n	轴承部位\n	检查轴承温度、润滑状态、振动情况。\n	温升平稳，润滑良好，振动无明显增大。\n	过热、异响、振动变大可能提示轴承磨损或润滑不足。\r\n	机械密封\n	检查密封处是否渗漏、滴漏或喷漏。\n	密封处无明显泄漏或仅有轻微允许渗漏。\n	泄漏增大可能提示密封磨损、安装偏差或压力异常。\r\n	进出水管路\n	检查管道连接、法兰、支架和水流状态。\n	管道无变形，法兰无渗漏，支架稳固。\n	管道振动、漏水、压力波动可能提示堵塞或水锤风险。\r\n	运行参数\n	核对流量、压力、电流、转速等参数。\n	参数处于正常运行范围内，变化趋势平稳。\n	流量不足、压力异常、电流升高需进一步排查。\r\n3.2 电机与电气系统巡检项目\n	巡检对象\n	检查内容\n	正常状态参考\n	异常提示\r\n	电机外壳\n	检查温度、噪声、振动、外观和接地情况。\n	外壳温度正常，接地可靠，运行平稳。\n	温度过高、异味、异常振动可能提示过载或绝缘问题。\r\n	电流电压\n	查看三相电流、电压是否平衡。\n	三相参数基本平衡，无明显波动。\n	电流偏高、电压不平衡可能导致电机发热或跳闸。\r\n	控制柜\n	检查指示灯、按钮、开关、接触器、继电器和显示屏。\n	指示正常，操作灵敏，柜内无异味和异响。\n	焦味、打火声、接线发热应立即停机检查。\r\n	电缆接线\n	检查线缆外皮、端子紧固和穿管保护。\n	线缆无破损，端', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (365, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, '2f16d746-90d6-41bc-9245-27c23424d9c8', 3, NULL, '查指示灯、按钮、开关、接触器、继电器和显示屏。\n	指示正常，操作灵敏，柜内无异味和异响。\n	焦味、打火声、接线发热应立即停机检查。\r\n	电缆接线\n	检查线缆外皮、端子紧固和穿管保护。\n	线缆无破损，端子无松动，标识清楚。\n	破皮、松动、过热可能引发短路或接触不良。\r\n	保护装置\n	检查过载、漏电、缺相、短路等保护功能状态。\n	保护装置状态正常，无频繁误动作。\n	频繁跳闸需排查负载、电源和保护整定。\r\n3.3 阀门、管道和仪表巡检项目\n	巡检对象\n	检查内容\n	维护重点\r\n	阀门\n	检查开度位置、启闭灵活性、阀杆润滑、阀体渗漏。\n	长期不动作阀门应定期试启闭，防止锈蚀卡涩。\r\n	管道\n	检查腐蚀、变形、渗漏、支架松动、异常振动。\n	发现渗漏或支架松动应及时处理，避免扩大损坏。\r\n	压力表\n	检查指针是否灵敏、量程是否合适、读数是否稳定。\n	指针不回零、读数跳动大或表盘损坏时应更换或校验。\r\n	流量计\n	检查显示是否正常、信号是否稳定、安装段是否有异常。\n	信号异常应检查传感器、电源、通信线和管道工况。\r\n	液位计\n	检查液位显示、报警联动、探头清洁情况。\n	液位异常会影响启停控制，应定期清洁和校验。\r\n	传感器\n	检查温度、振动、电流等传感器固定和数据传输。\n	数据明显漂移时应进行校准或更换。\r\n4. 设备保养维护知识\n保养维护应覆盖清洁、紧固、润滑、调整、防腐、校验和功能测试等方面。保养前应确认设备状态，必要时办理停机、断电、挂牌和安全确认手续。保养后应进行试运行，并记录保养内容、发现问题和处理结果。\n	保养类别\n	主要内容\n	建议周期\n	注意事项\r\n	清洁保养\n	清理泵体、电机、控制柜外部、仪表表面、排水沟和泵房环境。\n	每日或每班\n	控制柜内部清洁应由专业人员在断电后进行。\r\n	紧固保养\n	检查地脚螺栓、联轴器护罩、管道支架、端子排和接线螺丝。\n	每周或每月\n	紧固前应确认设备停稳，防止旋转部位伤人。\r\n	润滑保养\n	按设备要求补充或更换轴承润滑脂、阀杆润滑油等。\n	按说明书或运行小时数\n	不得混用不同型号润滑脂，避免过量加注。\r\n	防腐保养\n	检查管道、支架、泵体和基础金属构件的锈蚀情况。\n	每季度或半年\n	潮湿环境、地下泵房和沿海区域应提高防腐频次。\r\n	仪表校验\n	校验压力表、流量计、液位计、温度和振动传感器。\n	按计量要求或年度计划\n	关键仪表应保留校验记录和有效期。\r\n	功能测试\n	测试启停、联锁、报警、自动控制和备用泵切换功能。\n	每月或季度\n	测试前应评估对生产运行和供排水安全的影响。\r\n5. 预防性维护策略\n预防性维护不是简单地按时间检修，而是结合运行工况、设备状态、历史故障、关键程度和环', '查指示灯、按钮、开关、接触器、继电器和显示屏。\n	指示正常，操作灵敏，柜内无异味和异响。\n	焦味、打火声、接线发热应立即停机检查。\r\n	电缆接线\n	检查线缆外皮、端子紧固和穿管保护。\n	线缆无破损，端子无松动，标识清楚。\n	破皮、松动、过热可能引发短路或接触不良。\r\n	保护装置\n	检查过载、漏电、缺相、短路等保护功能状态。\n	保护装置状态正常，无频繁误动作。\n	频繁跳闸需排查负载、电源和保护整定。\r\n3.3 阀门、管道和仪表巡检项目\n	巡检对象\n	检查内容\n	维护重点\r\n	阀门\n	检查开度位置、启闭灵活性、阀杆润滑、阀体渗漏。\n	长期不动作阀门应定期试启闭，防止锈蚀卡涩。\r\n	管道\n	检查腐蚀、变形、渗漏、支架松动、异常振动。\n	发现渗漏或支架松动应及时处理，避免扩大损坏。\r\n	压力表\n	检查指针是否灵敏、量程是否合适、读数是否稳定。\n	指针不回零、读数跳动大或表盘损坏时应更换或校验。\r\n	流量计\n	检查显示是否正常、信号是否稳定、安装段是否有异常。\n	信号异常应检查传感器、电源、通信线和管道工况。\r\n	液位计\n	检查液位显示、报警联动、探头清洁情况。\n	液位异常会影响启停控制，应定期清洁和校验。\r\n	传感器\n	检查温度、振动、电流等传感器固定和数据传输。\n	数据明显漂移时应进行校准或更换。\r\n4. 设备保养维护知识\n保养维护应覆盖清洁、紧固、润滑、调整、防腐、校验和功能测试等方面。保养前应确认设备状态，必要时办理停机、断电、挂牌和安全确认手续。保养后应进行试运行，并记录保养内容、发现问题和处理结果。\n	保养类别\n	主要内容\n	建议周期\n	注意事项\r\n	清洁保养\n	清理泵体、电机、控制柜外部、仪表表面、排水沟和泵房环境。\n	每日或每班\n	控制柜内部清洁应由专业人员在断电后进行。\r\n	紧固保养\n	检查地脚螺栓、联轴器护罩、管道支架、端子排和接线螺丝。\n	每周或每月\n	紧固前应确认设备停稳，防止旋转部位伤人。\r\n	润滑保养\n	按设备要求补充或更换轴承润滑脂、阀杆润滑油等。\n	按说明书或运行小时数\n	不得混用不同型号润滑脂，避免过量加注。\r\n	防腐保养\n	检查管道、支架、泵体和基础金属构件的锈蚀情况。\n	每季度或半年\n	潮湿环境、地下泵房和沿海区域应提高防腐频次。\r\n	仪表校验\n	校验压力表、流量计、液位计、温度和振动传感器。\n	按计量要求或年度计划\n	关键仪表应保留校验记录和有效期。\r\n	功能测试\n	测试启停、联锁、报警、自动控制和备用泵切换功能。\n	每月或季度\n	测试前应评估对生产运行和供排水安全的影响。\r\n5. 预防性维护策略\n预防性维护不是简单地按时间检修，而是结合运行工况、设备状态、历史故障、关键程度和环', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (366, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, '843ba5f9-7b49-423d-81c6-0bdcd9dce334', 4, NULL, '报警、自动控制和备用泵切换功能。\n	每月或季度\n	测试前应评估对生产运行和供排水安全的影响。\r\n5. 预防性维护策略\n预防性维护不是简单地按时间检修，而是结合运行工况、设备状态、历史故障、关键程度和环境条件制定维护计划。对关键泵组、长期高负荷设备、故障频发部件和安全相关设备，应实施重点预防维护。\n	策略类型\n	适用场景\n	实施方式\n	预期效果\r\n	定期维护\n	设备运行稳定、维护周期明确的常规设备。\n	按照日、周、月、季、年度计划执行保养。\n	保证基础维护不缺项，降低常规故障。\r\n	状态维护\n	安装传感器并具备运行数据的关键设备。\n	根据振动、温度、电流、压力等趋势决定维护时机。\n	减少过度维修，提前发现劣化趋势。\r\n	重点维护\n	故障影响大、停机会造成较大损失的设备。\n	设置重点点检项目和专项维护计划。\n	提高关键设备可靠性。\r\n	隐患闭环\n	巡检发现异常但尚未形成故障的情况。\n	记录隐患、制定措施、限期整改、复查确认。\n	防止隐患反复出现或扩大。\r\n	备件预控\n	易损件消耗明显或采购周期较长的设备。\n	建立轴承、密封、传感器、接触器等备件清单。\n	缩短故障恢复时间。\r\n5.1 推荐维护周期表\n	周期\n	维护重点\n	主要任务\r\n	每日/每班\n	运行状态确认\n	记录流量、压力、液位、电流、电压、振动、温度；检查声音、泄漏、异味和报警。\r\n	每周\n	基础维护和清洁\n	清洁设备表面，检查螺栓、管道支架、阀门开度、排水沟和泵房环境。\r\n	每月\n	功能检查和小保养\n	检查备用泵切换、报警联动、控制柜散热、传感器固定和仪表显示。\r\n	每季度\n	专项检查\n	检查联轴器、轴承润滑、防腐状况、电气接线、阀门启闭灵活性。\r\n	每半年\n	性能和隐患评估\n	分析运行趋势，排查振动升高、效率下降、能耗增加、漏水增多等问题。\r\n	每年\n	全面保养和评估\n	进行综合检修、仪表校验、保护功能测试、维护制度复盘和备件清单更新。\r\n6. 常见隐患与预防措施\n	隐患类型\n	可能表现\n	预防措施\r\n	轴承润滑不足\n	轴承温度升高、运行异响、振动增大。\n	按周期补充或更换润滑脂，关注温度和振动趋势，避免缺油或过量加油。\r\n	机械密封磨损\n	密封处滴漏增大、泵房积水、压力波动。\n	定期检查密封泄漏量，关注干运行、杂质磨损和安装偏差。\r\n	管道堵塞或结垢\n	流量下降、压力异常、能耗增加。\n	定期冲洗管道，检查过滤装置，结合水质情况安排清淤除垢。\r\n	阀门卡涩\n	启闭困难、开度不准、阀杆锈蚀。\n	定期试启闭，清洁阀杆并润滑，长期不用阀门应列入点检。\r\n	电机过热\n	电流偏高、外壳温度升高、有异味。\n	检查负荷、电源、电压平衡、散热条件和轴承状态。\r\n	控制', '报警、自动控制和备用泵切换功能。\n	每月或季度\n	测试前应评估对生产运行和供排水安全的影响。\r\n5. 预防性维护策略\n预防性维护不是简单地按时间检修，而是结合运行工况、设备状态、历史故障、关键程度和环境条件制定维护计划。对关键泵组、长期高负荷设备、故障频发部件和安全相关设备，应实施重点预防维护。\n	策略类型\n	适用场景\n	实施方式\n	预期效果\r\n	定期维护\n	设备运行稳定、维护周期明确的常规设备。\n	按照日、周、月、季、年度计划执行保养。\n	保证基础维护不缺项，降低常规故障。\r\n	状态维护\n	安装传感器并具备运行数据的关键设备。\n	根据振动、温度、电流、压力等趋势决定维护时机。\n	减少过度维修，提前发现劣化趋势。\r\n	重点维护\n	故障影响大、停机会造成较大损失的设备。\n	设置重点点检项目和专项维护计划。\n	提高关键设备可靠性。\r\n	隐患闭环\n	巡检发现异常但尚未形成故障的情况。\n	记录隐患、制定措施、限期整改、复查确认。\n	防止隐患反复出现或扩大。\r\n	备件预控\n	易损件消耗明显或采购周期较长的设备。\n	建立轴承、密封、传感器、接触器等备件清单。\n	缩短故障恢复时间。\r\n5.1 推荐维护周期表\n	周期\n	维护重点\n	主要任务\r\n	每日/每班\n	运行状态确认\n	记录流量、压力、液位、电流、电压、振动、温度；检查声音、泄漏、异味和报警。\r\n	每周\n	基础维护和清洁\n	清洁设备表面，检查螺栓、管道支架、阀门开度、排水沟和泵房环境。\r\n	每月\n	功能检查和小保养\n	检查备用泵切换、报警联动、控制柜散热、传感器固定和仪表显示。\r\n	每季度\n	专项检查\n	检查联轴器、轴承润滑、防腐状况、电气接线、阀门启闭灵活性。\r\n	每半年\n	性能和隐患评估\n	分析运行趋势，排查振动升高、效率下降、能耗增加、漏水增多等问题。\r\n	每年\n	全面保养和评估\n	进行综合检修、仪表校验、保护功能测试、维护制度复盘和备件清单更新。\r\n6. 常见隐患与预防措施\n	隐患类型\n	可能表现\n	预防措施\r\n	轴承润滑不足\n	轴承温度升高、运行异响、振动增大。\n	按周期补充或更换润滑脂，关注温度和振动趋势，避免缺油或过量加油。\r\n	机械密封磨损\n	密封处滴漏增大、泵房积水、压力波动。\n	定期检查密封泄漏量，关注干运行、杂质磨损和安装偏差。\r\n	管道堵塞或结垢\n	流量下降、压力异常、能耗增加。\n	定期冲洗管道，检查过滤装置，结合水质情况安排清淤除垢。\r\n	阀门卡涩\n	启闭困难、开度不准、阀杆锈蚀。\n	定期试启闭，清洁阀杆并润滑，长期不用阀门应列入点检。\r\n	电机过热\n	电流偏高、外壳温度升高、有异味。\n	检查负荷、电源、电压平衡、散热条件和轴承状态。\r\n	控制', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (367, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, '0dde3aaa-0eea-437d-a636-26a70dc5d83c', 5, NULL, '\n	启闭困难、开度不准、阀杆锈蚀。\n	定期试启闭，清洁阀杆并润滑，长期不用阀门应列入点检。\r\n	电机过热\n	电流偏高、外壳温度升高、有异味。\n	检查负荷、电源、电压平衡、散热条件和轴承状态。\r\n	控制柜受潮\n	端子氧化、绝缘下降、误报警或跳闸。\n	保持柜内干燥通风，检查密封和除湿设施，定期清洁灰尘。\r\n	仪表数据漂移\n	显示值与现场实际不一致，趋势异常。\n	定期校验仪表，检查传感器安装、线缆和通信状态。\r\n	泵房排水不畅\n	地面积水、设备基础受潮、腐蚀加重。\n	保持排水沟通畅，定期清理杂物，检查排水泵和液位控制。\r\n7. 巡检与维护记录模板\n记录模板用于保证巡检维护信息可追溯。实际使用时可根据泵站管理系统要求增加设备编号、位置、巡检人员、复核人员、整改闭环状态等字段。\n	记录字段\n	填写说明\n	示例\r\n	设备名称/编号\n	填写具体泵组、电机、阀门、控制柜或仪表编号。\n	1#提升泵、2#排水泵\r\n	巡检时间\n	填写具体日期和时间。\n	2026-06-01 09:00\r\n	运行状态\n	填写运行、备用、停机、检修等状态。\n	运行\r\n	关键参数\n	记录流量、压力、电流、温度、振动等数据。\n	压力0.45MPa，电流52A\r\n	检查结果\n	填写正常或异常，并简要描述异常现象。\n	轴承声音正常，密封无明显泄漏\r\n	处理措施\n	填写现场处理、上报、继续观察或安排维修。\n	继续观察；下班次复查\r\n	复查结果\n	异常处理后填写复查情况。\n	复查正常\r\n	备注\n	填写特殊工况、天气、运行方式变化等补充信息。\n	雨后加强排水检查\r\n7.1 巡检异常分级建议\n	等级\n	判定说明\n	处理建议\r\n	一般异常\n	轻微渗漏、轻微异响、参数小幅波动，但设备仍能稳定运行。\n	记录并跟踪趋势，安排计划性处理。\r\n	较大异常\n	振动、温度、电流、压力等指标明显异常，存在发展为故障的风险。\n	及时上报，缩短复查周期，必要时切换备用设备。\r\n	严重异常\n	出现冒烟、焦味、剧烈振动、大量泄漏、频繁跳闸、保护动作等情况。\n	立即停机或按应急预案处理，严禁带故障运行。\r\n8. 安全注意事项\n	现场安全提醒\n• 检修维护前应确认停机、断电、泄压、挂牌和现场隔离措施。\n• 不得触碰旋转部位、带电部位、高温部位和高压管路。\n• 泵房潮湿环境作业时应注意防滑、防触电和通风。\n• 涉及电气检查、控制柜内部操作和保护装置调整时，应由具备相应能力的人员执行。\n• 发现重大异常时，应优先保证人员安全，再进行设备处置。\r\n本文件提供的是知识库通用维护知识，现场执行时必须结合本单位安全管理制度、设备使用说明书、检修规程和应急预案。涉及带电、高压、起吊、有限空间、动火等高风险作业', '\n	启闭困难、开度不准、阀杆锈蚀。\n	定期试启闭，清洁阀杆并润滑，长期不用阀门应列入点检。\r\n	电机过热\n	电流偏高、外壳温度升高、有异味。\n	检查负荷、电源、电压平衡、散热条件和轴承状态。\r\n	控制柜受潮\n	端子氧化、绝缘下降、误报警或跳闸。\n	保持柜内干燥通风，检查密封和除湿设施，定期清洁灰尘。\r\n	仪表数据漂移\n	显示值与现场实际不一致，趋势异常。\n	定期校验仪表，检查传感器安装、线缆和通信状态。\r\n	泵房排水不畅\n	地面积水、设备基础受潮、腐蚀加重。\n	保持排水沟通畅，定期清理杂物，检查排水泵和液位控制。\r\n7. 巡检与维护记录模板\n记录模板用于保证巡检维护信息可追溯。实际使用时可根据泵站管理系统要求增加设备编号、位置、巡检人员、复核人员、整改闭环状态等字段。\n	记录字段\n	填写说明\n	示例\r\n	设备名称/编号\n	填写具体泵组、电机、阀门、控制柜或仪表编号。\n	1#提升泵、2#排水泵\r\n	巡检时间\n	填写具体日期和时间。\n	2026-06-01 09:00\r\n	运行状态\n	填写运行、备用、停机、检修等状态。\n	运行\r\n	关键参数\n	记录流量、压力、电流、温度、振动等数据。\n	压力0.45MPa，电流52A\r\n	检查结果\n	填写正常或异常，并简要描述异常现象。\n	轴承声音正常，密封无明显泄漏\r\n	处理措施\n	填写现场处理、上报、继续观察或安排维修。\n	继续观察；下班次复查\r\n	复查结果\n	异常处理后填写复查情况。\n	复查正常\r\n	备注\n	填写特殊工况、天气、运行方式变化等补充信息。\n	雨后加强排水检查\r\n7.1 巡检异常分级建议\n	等级\n	判定说明\n	处理建议\r\n	一般异常\n	轻微渗漏、轻微异响、参数小幅波动，但设备仍能稳定运行。\n	记录并跟踪趋势，安排计划性处理。\r\n	较大异常\n	振动、温度、电流、压力等指标明显异常，存在发展为故障的风险。\n	及时上报，缩短复查周期，必要时切换备用设备。\r\n	严重异常\n	出现冒烟、焦味、剧烈振动、大量泄漏、频繁跳闸、保护动作等情况。\n	立即停机或按应急预案处理，严禁带故障运行。\r\n8. 安全注意事项\n	现场安全提醒\n• 检修维护前应确认停机、断电、泄压、挂牌和现场隔离措施。\n• 不得触碰旋转部位、带电部位、高温部位和高压管路。\n• 泵房潮湿环境作业时应注意防滑、防触电和通风。\n• 涉及电气检查、控制柜内部操作和保护装置调整时，应由具备相应能力的人员执行。\n• 发现重大异常时，应优先保证人员安全，再进行设备处置。\r\n本文件提供的是知识库通用维护知识，现场执行时必须结合本单位安全管理制度、设备使用说明书、检修规程和应急预案。涉及带电、高压、起吊、有限空间、动火等高风险作业', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (368, 1001, '泵站设备日常巡检保养与预防性维护知识.docx', 49, '37aa3bb5-7908-44a5-89d6-073a13335145', 6, NULL, '时，应优先保证人员安全，再进行设备处置。\r\n本文件提供的是知识库通用维护知识，现场执行时必须结合本单位安全管理制度、设备使用说明书、检修规程和应急预案。涉及带电、高压、起吊、有限空间、动火等高风险作业时，应按现场审批流程执行。\n9. 知识库使用建议\n建议将本文件拆分或标注为多个知识条目，便于系统检索和问答调用。每个知识条目可设置“设备对象、故障风险、巡检项目、维护周期、处理建议、关联案例、关联备件”等字段，从而提高知识库命中率和可用性。\n	知识条目\n	建议标签\n	可关联文件\r\n	水泵日常巡检要求\n	水泵、巡检、振动、温度、密封\n	03_故障现象知识；05_诊断方法知识\r\n	电机维护保养要求\n	电机、电流、电压、温升、接地\n	04_故障原因知识；07_维修处理知识\r\n	阀门和管道预防维护\n	阀门、管道、泄漏、堵塞、防腐\n	06_解决方案知识；08_典型案例知识\r\n	仪表传感器校验维护\n	压力表、流量计、液位计、传感器、校验\n	02_状态监测知识；05_诊断方法知识\r\n	隐患闭环管理\n	隐患、整改、复查、记录、闭环\n	08_典型案例知识；10_安全操作知识\r\n附录：可直接上传的文件备注\n	文件备注\n• 用于整理泵站设备日常巡检、定期保养、预防性维护和隐患排查知识，帮助运维人员提前发现设备异常、规范维护流程、降低故障发生概率，并为泵站常见故障排查及解决方案库提供预防维护类知识支撑。\r\n09_泵站设备日常巡检保养与预防性维护知识', '时，应优先保证人员安全，再进行设备处置。\r\n本文件提供的是知识库通用维护知识，现场执行时必须结合本单位安全管理制度、设备使用说明书、检修规程和应急预案。涉及带电、高压、起吊、有限空间、动火等高风险作业时，应按现场审批流程执行。\n9. 知识库使用建议\n建议将本文件拆分或标注为多个知识条目，便于系统检索和问答调用。每个知识条目可设置“设备对象、故障风险、巡检项目、维护周期、处理建议、关联案例、关联备件”等字段，从而提高知识库命中率和可用性。\n	知识条目\n	建议标签\n	可关联文件\r\n	水泵日常巡检要求\n	水泵、巡检、振动、温度、密封\n	03_故障现象知识；05_诊断方法知识\r\n	电机维护保养要求\n	电机、电流、电压、温升、接地\n	04_故障原因知识；07_维修处理知识\r\n	阀门和管道预防维护\n	阀门、管道、泄漏、堵塞、防腐\n	06_解决方案知识；08_典型案例知识\r\n	仪表传感器校验维护\n	压力表、流量计、液位计、传感器、校验\n	02_状态监测知识；05_诊断方法知识\r\n	隐患闭环管理\n	隐患、整改、复查、记录、闭环\n	08_典型案例知识；10_安全操作知识\r\n附录：可直接上传的文件备注\n	文件备注\n• 用于整理泵站设备日常巡检、定期保养、预防性维护和隐患排查知识，帮助运维人员提前发现设备异常、规范维护流程、降低故障发生概率，并为泵站常见故障排查及解决方案库提供预防维护类知识支撑。\r\n09_泵站设备日常巡检保养与预防性维护知识', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:00', NULL, NULL, '2026-06-01 15:30:00', NULL);
INSERT INTO `kmc_document_segment` VALUES (369, 1001, '泵站运行检修安全操作规范与注意事项.docx', 50, '1225fc0a-edf1-4438-9b1b-29a0fd4f68e8', 1, NULL, '安全操作规范 - 泵站设备故障诊断知识库\n安全操作规范\n泵站设备故障诊断知识库\n分类：知识类/安全操作知识\r\n安全操作规范用于降低泵站运行和检修过程中的人身、设备和供水安全风险。\n一、知识内容\n运行安全要求\n• 启泵前确认进出水阀门状态、液位、电源、控制方式和保护联锁正常。\n• 运行中不得随意解除保护装置，不得在异常振动或高温状态下长期运行。\n• 检修前执行停电、验电、挂牌、泄压、排水和机械防护确认。\n检修安全要求\n• 电气检修必须由具备资质人员实施，严禁带电拆接线。\n• 进入泵坑、管廊等空间前，应确认通风、照明和气体检测合格。\n• 吊装电机、水泵等重物时应检查吊点、吊具和作业半径。\n二、结构化知识表\n	风险点\n	控制措施\r\n	触电风险\n	停电挂牌、验电确认、使用绝缘工具和防护用品\r\n	机械伤害\n	安装防护罩，停机后等待转动部件完全停止\r\n	高压水/泄压风险\n	拆卸前泄压排水，严禁正对法兰和阀门泄放口\r\n	淹溺/滑跌\n	保持泵房排水畅通，地面防滑，夜间照明充分\r\n	误启动\n	检修期间锁定控制回路，设置现场警示牌\r\n三、上传与检索建议\n• 建议上传分类：知识类/安全操作知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '安全操作规范 - 泵站设备故障诊断知识库\n安全操作规范\n泵站设备故障诊断知识库\n分类：知识类/安全操作知识\r\n安全操作规范用于降低泵站运行和检修过程中的人身、设备和供水安全风险。\n一、知识内容\n运行安全要求\n• 启泵前确认进出水阀门状态、液位、电源、控制方式和保护联锁正常。\n• 运行中不得随意解除保护装置，不得在异常振动或高温状态下长期运行。\n• 检修前执行停电、验电、挂牌、泄压、排水和机械防护确认。\n检修安全要求\n• 电气检修必须由具备资质人员实施，严禁带电拆接线。\n• 进入泵坑、管廊等空间前，应确认通风、照明和气体检测合格。\n• 吊装电机、水泵等重物时应检查吊点、吊具和作业半径。\n二、结构化知识表\n	风险点\n	控制措施\r\n	触电风险\n	停电挂牌、验电确认、使用绝缘工具和防护用品\r\n	机械伤害\n	安装防护罩，停机后等待转动部件完全停止\r\n	高压水/泄压风险\n	拆卸前泄压排水，严禁正对法兰和阀门泄放口\r\n	淹溺/滑跌\n	保持泵房排水畅通，地面防滑，夜间照明充分\r\n	误启动\n	检修期间锁定控制回路，设置现场警示牌\r\n三、上传与检索建议\n• 建议上传分类：知识类/安全操作知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:03', NULL, NULL, '2026-06-01 15:30:03', NULL);
INSERT INTO `kmc_document_segment` VALUES (370, 1001, '泵站突发故障应急处置流程与抢修方案.docx', 51, 'a58aad2a-db17-49cc-b964-788bfd5aa981', 1, NULL, '应急处置方案 - 泵站设备故障诊断知识库\n应急处置方案\n泵站设备故障诊断知识库\n分类：知识类/应急处置知识\r\n应急处置方案用于指导值班人员在突发故障时快速判断、稳妥隔离、及时上报并恢复运行。\n一、知识内容\n应急处置原则\n• 先保障人员安全，再保障设备安全和供水连续性。\n• 先隔离危险源，再查明原因，严禁盲目强行启动。\n• 处置过程应保留报警、参数、照片和操作记录，便于复盘。\n二、结构化知识表\n	突发情况\n	处置步骤\n	后续要求\r\n	主泵突然停机\n	确认报警，启动备用泵，检查电源、保护和机械卡滞\n	分析停机原因，恢复前进行试运行\r\n	管道爆裂或严重泄漏\n	立即停泵，关闭相关阀门，设置警戒，组织排水\n	检查管道支撑、压力波动和阀门状态\r\n	电气跳闸\n	禁止反复强送电，检查保护代码、绝缘和负载\n	查明原因后复位，必要时联系电气专业人员\r\n	泵房进水\n	切断受影响电源，启动排水措施，转移重要设备\n	确认电气绝缘合格后方可恢复运行\r\n	振动剧烈或异响\n	立即降频或停机，检查轴承、联轴器、叶轮和基础\n	处理后进行空载和带载验证\r\n三、上传与检索建议\n• 建议上传分类：知识类/应急处置知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', '应急处置方案 - 泵站设备故障诊断知识库\n应急处置方案\n泵站设备故障诊断知识库\n分类：知识类/应急处置知识\r\n应急处置方案用于指导值班人员在突发故障时快速判断、稳妥隔离、及时上报并恢复运行。\n一、知识内容\n应急处置原则\n• 先保障人员安全，再保障设备安全和供水连续性。\n• 先隔离危险源，再查明原因，严禁盲目强行启动。\n• 处置过程应保留报警、参数、照片和操作记录，便于复盘。\n二、结构化知识表\n	突发情况\n	处置步骤\n	后续要求\r\n	主泵突然停机\n	确认报警，启动备用泵，检查电源、保护和机械卡滞\n	分析停机原因，恢复前进行试运行\r\n	管道爆裂或严重泄漏\n	立即停泵，关闭相关阀门，设置警戒，组织排水\n	检查管道支撑、压力波动和阀门状态\r\n	电气跳闸\n	禁止反复强送电，检查保护代码、绝缘和负载\n	查明原因后复位，必要时联系电气专业人员\r\n	泵房进水\n	切断受影响电源，启动排水措施，转移重要设备\n	确认电气绝缘合格后方可恢复运行\r\n	振动剧烈或异响\n	立即降频或停机，检查轴承、联轴器、叶轮和基础\n	处理后进行空载和带载验证\r\n三、上传与检索建议\n• 建议上传分类：知识类/应急处置知识。\n• 文件解析后可按“故障现象、可能原因、诊断依据、处理措施、预防建议”等关键词检索。\n泵站设备故障诊断知识库', 'null', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, 1, 0, NULL, NULL, '2026-06-01 15:30:04', NULL, NULL, '2026-06-01 15:30:04', NULL);
INSERT INTO `kmc_document` VALUES (18, 1001, 17, 9, NULL, '水泵运行异响振动故障', '水泵振动异响、机组晃动故障排查及解决方案.docx', '/2026/06/01/6a1cfd61f0b1d117b2b4628c.docx', '针对泵站运行过程中水泵本体出现异常噪音、机身剧烈振动、机组整体晃动等常见故障，梳理故障诱发原因、分步排查流程、标准化处理方案，同时明确日常巡检、维护预防措施，解决泵组机械运行不稳定问题，规避设备松动、磨损、开裂等次生故障。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:32:59', '吴同', 2, '2026-06-01 11:35:04', NULL);
INSERT INTO `kmc_document` VALUES (19, 1001, 18, 9, NULL, '水泵出水异常故障', '水泵不出水、出水压力不足、流量异常故障排查及解决方案.docx', '/2026/06/01/6a1cff77f0b1d117b2b4628d.docx', '聚焦水泵空转不出水、出水压力偏低/偏高、输水流量不达标、流量波动大等影响输水效能的核心故障，覆盖进水、泵体、出水全链路排查，提供针对性整改方案，保障泵站输水流量、压力满足工艺及供水要求。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:41:53', '吴同', 2, '2026-06-01 11:45:02', NULL);
INSERT INTO `kmc_document` VALUES (20, 1001, 21, 9, NULL, '电机温升过热故障', '电机过热、温升超标、烧毁预警故障排查及解决方案.docx', '/2026/06/01/6a1d00a6f0b1d117b2b4628e.docx', '针对电机运行温升过快、温度超标、机身发烫、高温报警等故障，区分过载、散热不良、电压异常、部件损坏等不同诱因，制定分级排查和整改方案，同时设置烧毁预警处置流程，有效预防电机线圈烧毁、设备报废问题。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:46:56', '吴同', 2, '2026-06-01 11:50:02', NULL);
INSERT INTO `kmc_document` VALUES (21, 1001, 22, 9, NULL, '电机异响卡滞故障', '电机启动失败、卡顿异响、运行无力故障排查及解决方案.docx', '/2026/06/01/6a1d02c0f0b1d117b2b4628f.docx', '解决电机无法启动、启动卡顿、运行异响、动力不足、带载能力差等故障，涵盖机械卡滞、电气缺相、电压不足、轴承损坏等各类问题场景，提供标准化排查步骤和修复方案，保障电机平稳启停、正常带载运行。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:56:03', '吴同', 2, '2026-06-01 12:00:02', NULL);
INSERT INTO `kmc_document` VALUES (22, 1001, 24, 9, NULL, '变频器故障', '变频器报警、故障停机、调频失效排查及解决方案.docx', '/2026/06/01/6a1d030bf0b1d117b2b46290.docx', '针对泵站变频器常见代码报警、突发故障停机、无法调频调速、转速不稳等故障，分类梳理故障类型、报错诱因，细化电气检测、参数调试、硬件检修流程，解决变频器调控失效问题，保障泵组变频稳压、稳流运行。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:57:02', '吴同', 2, '2026-06-01 12:00:03', NULL);
INSERT INTO `kmc_document` VALUES (23, 1001, 25, 9, NULL, '配电柜及线路故障', '泵站电气跳闸、漏电、线路故障排查及解决方案.docx', '/2026/06/01/6a1d039df0b1d117b2b46291.docx', '覆盖泵站配电柜、线缆、开关、接地系统引发的漏电、瞬时跳闸、频繁跳闸、线路发热破损等电气故障，明确安全排查规范、故障定位方法、修复整改措施，消除电气安全隐患，保障电气系统稳定供电。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 11:59:27', '吴同', 2, '2026-06-01 12:00:04', NULL);
INSERT INTO `kmc_document` VALUES (24, 1001, 27, 9, NULL, '液位压力流量仪表故障', '液位_压力_流量仪表数据不准、无反馈故障排查及解决方案.docx', '/2026/06/01/6a1d1a9ef0b1d117b2b46292.docx', '针对泵站液位、压力、流量传感器仪表数据漂移、数值不准、数据归零、无信号反馈等故障，梳理仪表校准、线路检测、设备检修、安装调试等全套流程，保障监测数据精准，为自控运行提供可靠数据支撑。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:37:36', '吴同', 2, '2026-06-01 13:40:02', NULL);
INSERT INTO `kmc_document` VALUES (25, 1001, 28, 9, NULL, '自动启停联动失效故障', 'PLC联动失效、远程监控通讯中断故障排查及解决方案.docx', '/2026/06/01/6a1d1bcef0b1d117b2b46293.docx', '聚焦PLC程序逻辑异常、设备联动启停失效、现场与后台通讯中断、远程监控无画面、无数据传输等故障，排查程序、模块、网络、线路问题，提供修复及调试方案，保障泵站自动化、远程化正常管控。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:42:41', '吴同', 2, '2026-06-01 13:45:03', NULL);
INSERT INTO `kmc_document` VALUES (26, 1001, 30, 9, NULL, '管路堵塞渗漏故障', '管路渗漏堵塞、阀门卡滞关闭不严故障排查及解决方案.docx', '/2026/06/01/6a1d1cadf0b1d117b2b46294.docx', '针对进出水管道渗漏、堵塞、积水淤积，以及闸阀、止回阀、蝶阀卡滞、开关不到位、关闭不严倒流等故障，制定管路清理、阀门检修、密封更换、管路修补标准化方案，保障管路系统通畅密闭。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:46:24', '吴同', 2, '2026-06-01 13:50:01', NULL);
INSERT INTO `kmc_document` VALUES (27, 1001, 31, 9, NULL, '管路压力异常故障', '过滤器堵塞、泵房积水排水不畅故障排查及解决方案.docx', '/2026/06/01/6a1d1d76f0b1d117b2b46295.docx', '围绕进水过滤器杂物堵塞、滤网淤积、过水不畅，以及泵房集水积水、排水泵启停异常、排水不及时等常见辅助故障，明确日常清理、故障排查、设备检修流程，保障泵房运行环境及输水通畅。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:49:44', '吴同', 2, '2026-06-01 13:50:03', NULL);
INSERT INTO `kmc_document` VALUES (28, 1001, 32, 9, NULL, '泵站配套辅助设备故障', '泵站机组频繁启停、运行不稳定综合故障排查及解决方案.docx', '/2026/06/01/6a1d1e45f0b1d117b2b46296.docx', '针对非人为操作导致的机组频繁启停、运行波动、工况不稳定等综合性疑难故障，整合机械、电气、自控、管路多维度排查逻辑，定位复合型故障诱因，提供综合整改及优化方案，提升泵站整体运行稳定性。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 13:53:13', '吴同', 2, '2026-06-01 13:55:01', NULL);
INSERT INTO `kmc_document` VALUES (29, 1001, 36, 14, NULL, '泵体及过流部件故障案例', '泵站泵体堵塞、叶轮损坏典型故障案例集.docx', '/2026/06/01/6a1d27b5f0b1d117b2b46299.docx', '收录市政污水泵站、排涝泵站、一体化泵站真实泵体杂物堵塞、纤维缠绕、叶轮磨损断裂、泵腔积气导致不出水的现场故障案例，每例包含故障发生场景、现象特征、现场排查过程、故障根因、整改处置措施及案例复盘总结，可直接用于运维参考与故障对标。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:33:32', '吴同', 2, '2026-06-01 14:54:16', NULL);
INSERT INTO `kmc_document` VALUES (30, 1001, 36, 14, NULL, '泵体及过流部件故障案例', '泵站机组振动、异响超标故障实战案例库.docx', '/2026/06/01/6a1d292df0b1d117b2b4629a.docx', '汇总各类泵站机组运行异响、剧烈振动、共振抖动真实故障案例，区分机械异响、水力异响、管路共振不同故障场景，详细记录案例排查思路、故障点位确认、整改施工过程、整改效果验证及同类问题预防经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:39:45', '吴同', 2, '2026-06-01 14:54:17', NULL);
INSERT INTO `kmc_document` VALUES (31, 1001, 37, 14, NULL, '轴承及密封机构故障案例', '泵站轴承过热、磨损抱死故障案例复盘集.docx', '/2026/06/01/6a1d29a2f0b1d117b2b4629b.docx', '收录机组轴承异响、温升超标、严重磨损、抱死停机等真实故障案例，完整记录每起案例的故障发生过程、运行参数特征、排查检测方式、拆解检修过程、更换整改方案，总结润滑失效、安装偏差、超负荷运行等诱因规律。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:41:42', '吴同', 2, '2026-06-01 14:54:18', NULL);
