INSERT INTO `kmc_document` VALUES (33, 1001, 39, 14, NULL, '电机运行异常故障案例', '泵站轴承过热、磨损抱死故障案例复盘集.docx', '/2026/06/01/6a1d2ab1f0b1d117b2b4629d.docx', '收录各类泵站电机运行过载、电流异常、机身高温、热保护跳闸停机的真实现场案例，详细记录案例运行工况、故障触发条件、多维度排查过程、根因判定、整改措施，梳理机械卡滞、水力过载、电气异常等不同诱因的案例特征。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:46:14', '吴同', 2, '2026-06-01 14:54:20', NULL);
