INSERT INTO `kmc_document` VALUES (35, 1001, 40, 14, NULL, '电气回路及元件故障案例', '泵站电气线路、开关元件故障实战案例库.docx', '/2026/06/01/6a1d2b34f0b1d117b2b4629f.docx', '收录空开频繁跳闸、接触器烧蚀粘连、线路虚接发热、短路断路、端子老化打火等电气真实故障案例，详细记录案例故障现象、检测排查过程、元件更换整改方案，总结日常运维中高频电气隐患案例规律。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:48:23', '吴同', 2, '2026-06-01 14:54:22', NULL);
INSERT INTO `kmc_document` VALUES (36, 1001, 42, 14, NULL, '控制及变频故障案例', '泵站变频器报错、变频异常故障案例复盘.docx', '/2026/06/01/6a1d2b7ef0b1d117b2b462a0.docx', '汇总变频器各类故障代码报警、频率波动、变频无法启动、运行跳闸、低速工况异常等真实现场案例，结合具体案例解读故障代码含义、故障排查步骤、参数优化、硬件整改方案，沉淀变频系统故障处置经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:49:37', '吴同', 2, '2026-06-01 14:54:23', NULL);
