INSERT INTO `kmc_document` VALUES (39, 1001, 45, 14, NULL, '机组工况异常故障案例', '泵站机组出力不足、工况异常典型故障案例.docx', '/2026/06/01/6a1d2c4cf0b1d117b2b462a3.docx', '收录水泵出水偏小、扬程不足、流量不稳、机组空转、频繁启停、工况漂移等高频工况异常真实案例，结合不同泵站运行场景，溯源机械、水力、自控系统问题，完整记录案例排查、整改优化过程及长效防控经验。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\n\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 14:53:03', '吴同', 2, '2026-06-01 14:54:25', NULL);
