INSERT INTO `kmc_document` VALUES (42, 1001, 54, 13, NULL, '状态监测知识', '泵站运行状态监测指标及关键参数采集知识.docx', '/2026/06/01/6a1d2fb7f0b1d117b2b462a9.docx', '用于整理泵站运行过程中的状态监测内容，包括流量、压力、液位、温度、振动、电流、电压、转速等关键运行参数，帮助判断设备是否处于正常运行状态。', 0, 0, 2, 'custom', 'paragraph', 1, 0, '50', 1024, '\\n\\n', 512, '\n', 'text_model', 'Chinese', NULL, NULL, NULL, NULL, NULL, 1, 0, '吴同', 2, '2026-06-01 15:07:37', '吴同', 2, '2026-06-01 15:15:01', NULL);
